static func generate_dungeon(dungeon_data: Dictionary) -> Dictionary:
	var rooms: Dictionary = {}
	var room_count: int = int(dungeon_data.get("room_count", 5))
	var monster_pool: Array = dungeon_data.get("monster_pool", ["goblin"])
	var boss_data: Dictionary = dungeon_data.get("boss", {})

	# Start at (0, 0) as Entrance
	var entrance_coord := Vector2i.ZERO
	var entrance := Room.new()
	entrance.id = 0
	entrance.coord = entrance_coord
	entrance.type = Room.RoomType.ENTRANCE
	entrance.is_visited = true
	entrance.is_cleared = true
	rooms[entrance_coord] = entrance

	# Choose a random direction to build rooms sequentially
	var current_coord := entrance_coord
	var directions := [Vector2i(0, 1), Vector2i(1, 0), Vector2i(0, -1), Vector2i(-1, 0)]
	directions.shuffle()
	var dir: Vector2i = directions[0]

	# Build intermediate rooms
	for i in range(1, room_count - 1):
		current_coord += dir

		var room := Room.new()
		room.id = i
		room.coord = current_coord

		# Distribute room types randomly
		var roll := randf()
		if roll < 0.5:
			room.type = Room.RoomType.COMBAT
			# Select 1-3 monsters from pool
			var count := randi_range(1, 3)
			for j in count:
				room.monster_ids.append(monster_pool.pick_random())
		elif roll < 0.7:
			room.type = Room.RoomType.TRAP
			room.event_id = "trapped_chest"
		elif roll < 0.9:
			room.type = Room.RoomType.LOOT
			room.loot_item_ids.append("gold_100")
			if randf() < 0.5:
				room.loot_item_ids.append("potion_healing")
		else:
			room.type = Room.RoomType.EMPTY

		if dungeon_data.get("tactical_rooms", {}).has(str(i)):
			room.type = Room.RoomType.EMPTY
			room.monster_ids.clear()
			room.loot_item_ids.clear()
			room.event_id = ""
		rooms[current_coord] = room

	# Place Boss room at the end
	current_coord += dir
	var boss_room := Room.new()
	boss_room.id = room_count - 1
	boss_room.coord = current_coord
	boss_room.type = Room.RoomType.BOSS

	var boss_id: String = boss_data.get("monster_id", "goblin_chief")
	boss_room.monster_ids.append(boss_id)

	rooms[current_coord] = boss_room

	print("[DungeonGenerator] Procedurally built dungeon with %d rooms." % rooms.size())
	return rooms

func _resolve_room_encounter(room: Room) -> void:
	if dungeon_data.get("tactical_rooms", {}).has(str(room.id)):
		_enter_local_room(str(room.id))
		return
	if room.is_cleared:
		hud.add_log("This room is empty and cleared.")
		return

	var tile_terrain := "plains"
	var current_tile := hex_grid.get_tile(party_position)
	if current_tile != null:
		tile_terrain = current_tile.get_terrain_name()

	match room.type:
		Room.RoomType.COMBAT:
			hud.add_log("[color=red]Monsters spotted! Prepare for battle.[/color]")
			_begin_room_combat(room)
			GameManager.enter_combat(room.monster_ids, false, GameManager.GameState.DUNGEON, tile_terrain)

		Room.RoomType.TRAP:
			# Pop up chest event
			var event_table := DataLoader.get_event_table("dungeon_events")
			var event_data: Dictionary = {}
			for ev in event_table.get("events", []):
				if ev["id"] == room.event_id:
					event_data = ev
					break

			if not event_data.is_empty():
				_trigger_dungeon_event_ui(event_data, room)
			else:
				room.is_cleared = true
				_save_dungeon_state_to_manager()

		Room.RoomType.LOOT:
			hud.add_log("[color=green]You found a treasure chest![/color]")
			# Grant loot items to the active character
			var char_data: Character = PartyManager.get_active_characters()[0] if not PartyManager.get_active_characters().is_empty() else PlayerManager.get_active_player().get("character")
			for item_id in room.loot_item_ids:
				if item_id.begins_with("gold_"):
					var amount: int = item_id.substr(5).to_int()
					char_data.inventory.gold += amount
					hud.add_log("%s received %d gold!" % [char_data.character_name, amount])
				else:
					char_data.inventory.add_item(item_id)
					var item_name: String = DataLoader.get_item(item_id).get("name", item_id)
					hud.add_log("%s received %s!" % [char_data.character_name, item_name])
			room.is_cleared = true
			_save_dungeon_state_to_manager()
			hud.update_hud()

		Room.RoomType.BOSS:
			hud.add_log("[color=purple]Entering the Boss Chamber! The guardian awaits.[/color]")
			_begin_room_combat(room)
			GameManager.enter_combat(room.monster_ids, false, GameManager.GameState.DUNGEON, tile_terrain)

		_:
			room.is_cleared = true
			_save_dungeon_state_to_manager()

func _trigger_dungeon_event_ui(event_data: Dictionary, room: Room) -> void:
	var dialog: EventDialog = event_dialog_scene.instantiate()
	add_child(dialog)
	dialog.popup_event(PlayerManager.get_active_player()["character"], event_data)

	dialog.event_resolved.connect(func(result: Dictionary):
		hud.add_log(result.get("message", "Trap resolved."))
		hud.update_hud()

		# Check if trap triggered combat
		var next_combat: Array = result.get("monsters", [])
		if not next_combat.is_empty():
			var tile_terrain := "plains"
			var current_tile := hex_grid.get_tile(party_position)
			if current_tile != null:
				tile_terrain = current_tile.get_terrain_name()
			_begin_room_combat(room)
			GameManager.enter_combat(next_combat, result.get("surprise", false), GameManager.GameState.DUNGEON, tile_terrain)
			return

		room.is_cleared = true
		_save_dungeon_state_to_manager()
		if PlayerManager.is_party_wiped():
			_handle_defeat()
	)

func _complete_pending_combat() -> Room:
	if pending_combat_room_id < 0:
		return null
	var completed_room: Room = null
	for room in rooms.values():
		if room is Room and room.id == pending_combat_room_id:
			completed_room = room
			break
	if completed_room == null:
		push_error("[DungeonState] Pending combat room %d was not found." % pending_combat_room_id)
		return null
	completed_room.is_cleared = true
	if local_rooms.has(str(completed_room.id)):
		local_rooms[str(completed_room.id)]["encounter_cleared"] = true
	if completed_room.type == Room.RoomType.BOSS:
		boss_defeated = true
	pending_combat_room_id = -1
	_save_dungeon_state_to_manager()
	return completed_room

func _clear_dungeon_successfully() -> void:
	hud.add_log("[color=green]DUNGEON CLEARED SUCCESSFULLY![/color]")
	if not GameManager.mark_dungeon_cleared(dungeon_id):
		hud.add_log("This dungeon has already been cleared. No duplicate rewards granted.")
		await get_tree().create_timer(1.0).timeout
		GameManager.exit_dungeon()
		return

	# Give campaign rewards to the party
	var active_members := PartyManager.get_active_characters()
	var active_char: Character = active_members[0] if not active_members.is_empty() else PlayerManager.get_active_player().get("character")
	var loot_list: Array = dungeon_data.get("loot", [])

	if loot_list.is_empty():
		active_char.inventory.add_item("crown_fragment")
		hud.add_log("%s claimed the Crown Fragment!" % active_char.character_name)
	else:
		for loot_item in loot_list:
			var item_id: String = loot_item.get("item_id", "")
			if not item_id.is_empty():
				if item_id.begins_with("gold_"):
					var amount: int = item_id.substr(5).to_int()
					active_char.inventory.gold += amount
					hud.add_log("%s received %d gold!" % [active_char.character_name, amount])
				else:
					active_char.inventory.add_item(item_id)
					var item_name: String = DataLoader.get_item(item_id).get("name", item_id)
					hud.add_log("%s received %s!" % [active_char.character_name, item_name])

	# Trigger Milestone Clear if specified
	var milestone_clear = dungeon_data.get("milestone_clear")
	if milestone_clear != null:
		GameManager.check_milestone(str(milestone_clear))

	# Return to overworld
	await get_tree().create_timer(3.0).timeout
	GameManager.exit_dungeon()


## --- System-row handlers (mirror OverworldState) ---

func _resolve_destination_tile(coord: Vector2i) -> void:
	var tile := hex_grid.get_tile(coord)
	if tile == null: return

	# 1. Check if it's a dungeon entrance
	if tile.terrain == HexTile.TerrainType.DUNGEON_ENTRANCE:
		hud.add_log("[color=purple]Stumbled upon a Dungeon entrance: %s![/color]" % tile.location_name)
		# Trigger entering dungeon state
		GameManager.enter_dungeon(tile.dungeon_id)
		return

	# 2. Check if it's a town
	if tile.terrain == HexTile.TerrainType.TOWN:
		var town_name := tile.location_name if not tile.location_name.is_empty() else "Elderwick"
		hud.add_log("[color=green]Entered Town: %s![/color]" % town_name)
		_trigger_shop_ui(town_name)
		return

	# 3. Trigger random event based on terrain table
	var event := EventSystem.trigger_event_for_tile(tile)
	if not event.is_empty():
		_trigger_event_ui(event)
	else:
		has_resolved_tile = true
		_recalculate_reachable()

func _trigger_event_ui(event_data: Dictionary) -> void:
	# Instantiate and show event dialog
	var dialog: EventDialog = event_dialog_scene.instantiate()
	add_child(dialog)
	dialog.popup_event(PlayerManager.get_active_player()["character"], event_data)

	# Block grid clicks until event is closed
	hex_grid.set_process_input(false)

	dialog.event_resolved.connect(func(result: Dictionary):
		hex_grid.set_process_input(true)
		has_resolved_tile = true

		# Log result
		var msg: String = result.get("message", "Event resolved.")
		hud.add_log("[color=light_blue]%s[/color]" % msg)

		# Check if event triggered combat
		var next_state_combat: Array = result.get("monsters", [])
		if not next_state_combat.is_empty():
			# Enter combat!
			var tile_terrain := "plains"
			var current_tile := hex_grid.get_tile(PartyManager.get_exploration_position())
			if current_tile != null:
				tile_terrain = current_tile.get_terrain_name()
			GameManager.enter_combat(next_state_combat, result.get("surprise", false), GameManager.GameState.OVERWORLD, tile_terrain)
			return

		# Check if event teleported player
		if result.get("teleported", false):
			var destination: Variant = _represented_travel_destination(result)
			if destination is Vector2i:
				PartyManager.move_exploration_party(destination)
				FogOfWar.update_visibility(hex_grid)
				hud.add_log("Teleported to represented hex %s!" % str(destination))
			else:
				hud.add_log("The teleport has no legal represented destination; the party stays where it is.")

		# Check milestone check triggers if any
		var milestone_trigger: String = result.get("milestone", "")
		if not milestone_trigger.is_empty():
			GameManager.check_milestone(milestone_trigger)

		if PlayerManager.is_party_wiped():
			_handle_party_wiped()
			return

		# Refresh HUD and highlights
		hud.update_hud()
		_recalculate_reachable()
	)


## Resolve travel only onto an actual tile on the current map. Explicit event
## coordinates are honored only when legal; random-location events choose from
## the same live, plane-aware legal candidates. Never synthesize a coordinate.

func _execute_end_turn_command(_command: PlayerCommand) -> void:
	if companion_roster_open:
		return
	# Clear active player path/reach highlights
	hex_grid.clear_highlights()

	# Pass turn to next player
	var new_round := PlayerManager.next_turn()
	if new_round:
		report_animal_messenger_notifications(GameManager.advance_campaign_time(86400))
	_start_player_turn()

func _execute_rest_command(command: PlayerCommand) -> void:
	if command == null or not command.is_valid() or companion_roster_open:
		return
	if command.rest_type() == "short_rest":
		var party := _get_party_characters()
		var short_res := RestRules.complete_short_rest(
			party,
			{"source": "overworld", "companion_roster_open": companion_roster_open},
			hud,
			Callable(),
			func(final_out: Dictionary) -> void:
				for rec in final_out.get("recoveries", []):
					if rec is Dictionary and not str(rec.get("message", "")).is_empty():
						hud.add_log("[color=cyan]%s[/color]" % str(rec["message"]))
				hud.update_hud()
		)
		if not bool(short_res.get("success", false)):
			hud.add_log("[color=orange]%s[/color]" % str(short_res.get("message", "Cannot rest right now.")))
			return
		report_animal_messenger_notifications(short_res.get("notifications", []))
		hud.add_log("[color=cyan]The party takes a Short Rest (1 hour). Short-rest features recovered.[/color]")
		hud.update_hud()
		_recalculate_reachable()
		return
	var long_res := RestRules.complete_long_rest(
		_get_party_characters(),
		{"source": "overworld", "companion_roster_open": companion_roster_open}
	)
	if not bool(long_res.get("success", false)):
		hud.add_log("[color=orange]%s[/color]" % str(long_res.get("message", "Cannot rest right now.")))
		return
	report_animal_messenger_notifications(long_res.get("notifications", []))
	hud.add_log("[color=green]The party makes camp and rests. HP, spell slots, and feature uses restored.[/color]")
	hud.update_hud()
	_recalculate_reachable()

	# Ambush check: the most stealthy party member tries to keep the camp quiet.
	var dc := _compute_ambush_dc()
	var best_stealth := _party_best_stealth_mod()
	var best_char := _party_best_stealth_character()
	var roll := 0
	var total := 0
	if best_char != null:
		var stealth_check := EventResolver.resolve_skill_check(best_char, {"ability": "DEX", "skill": "Stealth", "dc": dc})
		roll = int(stealth_check.get("roll", 0))
		best_stealth = int(stealth_check.get("modifier", best_stealth))
		total = int(stealth_check.get("total", roll + best_stealth))
	else:
		hud.add_log("Nobody is able to keep watch over the camp.")
		return
	hud.add_log("[color=yellow]Stealth check: %d (rolled %d + %d) vs DC %d.[/color]" % [total, roll, best_stealth, dc])

	if total >= dc:
		hud.add_log("[color=green]The camp stays hidden. The night passes peacefully.[/color]")
	else:
		var ambush_pool := ["goblin", "wolf", "bandit", "giant_spider", "skeleton"]
		var count := randi_range(2, 3)
		var monsters: Array[String] = []
		for i in count:
			monsters.append(ambush_pool.pick_random())
		var tile_terrain := "plains"
		var current_tile := hex_grid.get_tile(PartyManager.get_exploration_position())
		if current_tile != null:
			tile_terrain = current_tile.get_terrain_name()
		hud.add_log("[color=red]Ambush! A %s pack stalks the camp![/color]" % tile_terrain)
		GameManager.enter_combat(monsters, true, GameManager.GameState.OVERWORLD, tile_terrain)


## Ambush Stealth DC: base 12, +1 per extra party member (more people = noisier).

func _compute_ambush_dc() -> int:
	var party_size := PlayerManager.get_player_count()
	return 12 + maxi(0, party_size - 1)


## Best party Stealth bonus (DEX mod + proficiency/expertise if Stealth-trained), over
## all alive characters. Used as the static part of the ambush Stealth check.

func _on_choice_selected(option: Dictionary) -> void:
	var command := PlayerCommand.event_choice(option)
	if command == null:
		return
	option = command.payload["option"]
	chosen_option = option

	# Check if this choice requires a skill check
	var check_data: Dictionary = option.get("check", {})
	if not check_data.is_empty():
		_setup_skill_check_section(option, str(event.get("id", "")))
	else:
		# Direct effects
		var effects: Array = option.get("effects", [])
		var results := EventResolver.apply_effects(active_character, effects)

		var outcomes_msg: String = option.get("description", "You proceed.")
		for res in results:
			outcomes_msg += "\n" + res.get("message", "")
			if res.get("type", "") == "start_combat":
				triggered_combat = res.get("monster_ids", [])
			if res.get("type", "") == "teleport_random":
				teleported = true

		desc_label.text = outcomes_msg
		choice_container.visible = false
		btn_close.visible = true

func _resolve_check_outcome(outcome_data: Dictionary, success: bool) -> void:
	var desc: String = outcome_data.get("description", "Outcome resolved.")
	var effects: Array = outcome_data.get("effects", [])
	var results := EventResolver.apply_effects(active_character, effects)

	for res in results:
		desc += "\n" + res.get("message", "")
		if res.get("type", "") == "start_combat":
			triggered_combat = res.get("monster_ids", [])
		if res.get("type", "") == "teleport_random":
			teleported = true

	# Wait a small delay to see the roll, then show outcome
	await get_tree().create_timer(1.2).timeout

	roll_section.visible = false
	desc_label.text = desc
	btn_close.visible = true

func _resolve_chain_event() -> void:
	var effects: Array = event.get("effects", [])
	var results := EventResolver.apply_effects(active_character, effects)

	# Log chain start
	var desc: String = event.get("description", "")
	for res in results:
		desc += "\n" + res.get("message", "")
		if res.get("type", "") == "teleport_random":
			teleported = true

	desc_label.text = desc

	# Instead of closing, clicking next button triggers the chain sub-event
	btn_close.text = "Next event..."
	btn_close.visible = true

	# Override close button to trigger chain
	btn_close.pressed.disconnect(_on_close_pressed)
	btn_close.pressed.connect(func():
		var chain_evt := EventChain.get_chain_event(event)
		if not chain_evt.is_empty():
			popup_event(active_character, chain_evt)
			btn_close.text = "Close"
			btn_close.visible = false
			btn_close.pressed.connect(_on_close_pressed, CONNECT_ONE_SHOT)
		else:
			_on_close_pressed()
	, CONNECT_ONE_SHOT)

func _on_close_pressed() -> void:
	# Emit event finished result to overworld
	var result := {
		"message": title_label.text + " resolved.",
		"monsters": triggered_combat,
		"teleported": teleported,
		"check_result": last_skill_check_result.duplicate(true),
	}
	event_resolved.emit(result)
	queue_free()

static func _apply_single_effect(character: Character, effect: Dictionary, roller: Character = null, casting_ability: String = "") -> Dictionary:
	var effect_type: String = effect.get("type", "")
	if roller == null:
		roller = character

	match effect_type:
		"nourish":
			var days := maxi(1, int(effect.get("days", 1)))
			character.add_nourishment(days)
			return {"type": "nourish", "days": days, "message": "%s has food for %d day%s." % [character.character_name, days, "" if days == 1 else "s"]}

		"damage":
			var damage_str: String = effect.get("value", "1d6")
			var modifiers := character.ability_scores.get_all_modifiers()
			modifiers["level"] = character.level
			var amount := Dice.parse_dice_string(damage_str, modifiers)
			var actual := int(CombatAction.resolve_damage(character, amount, str(effect.get("damage_type", "")))["damage"])
			return {"type": "damage", "amount": actual, "damage_type": effect.get("damage_type", ""), "message": "%s took %d %s damage!" % [character.character_name, actual, effect.get("damage_type", "")]}

		"heal":
			var heal_str := _level_scaled_expression(effect, "value_by_level", "value", character.level, "1d6")
			var modifiers := character.ability_scores.get_all_modifiers()
			modifiers["level"] = character.level
			var amount := Dice.parse_dice_string(heal_str, modifiers, roller)
			amount = SpellEffects.maximize_healing(character, amount, Dice.maximum_dice_string(heal_str, modifiers))
			if bool(effect.get("ability_bonus_from_caster", false)) and roller != null:
				amount += roller.ability_scores.get_ability_modifier(casting_ability if casting_ability in AbilityScores.ABILITIES else roller.get_spellcasting_ability())
			amount = maxi(0, amount)
			var actual := character.heal(amount)
			return {"type": "heal", "amount": actual, "message": "%s healed %d HP!" % [character.character_name, actual]}

		"heal_self":
			var heal_str := _level_scaled_expression(effect, "value_by_level", "value", character.level, "1d6")
			var modifiers := character.ability_scores.get_all_modifiers()
			modifiers["level"] = character.level
			var amount := maxi(0, Dice.parse_dice_string(heal_str, modifiers, roller))
			amount = SpellEffects.maximize_healing(character, amount, Dice.maximum_dice_string(heal_str, modifiers))
			var actual := character.heal(amount)
			return {"type": "heal", "amount": actual, "message": "%s healed %d HP!" % [character.character_name, actual]}

		"temporary_hp":
			var temp_str := _level_scaled_expression(effect, "value_by_level", "value", character.level, "1d6")
			var modifiers := character.ability_scores.get_all_modifiers()
			modifiers["level"] = character.level
			var temp_amount := Dice.parse_dice_string(temp_str, modifiers, roller)
			if temp_amount <= character.temp_hp:
				return {"type": "temporary_hp", "amount": 0, "message": "%s keeps their existing temporary HP." % character.character_name}
			character.temp_hp = temp_amount
			return {"type": "temporary_hp", "amount": temp_amount, "message": "%s gains %d temporary HP!" % [character.character_name, temp_amount]}

		"full_heal":
			var actual := character.heal(character.max_hp)
			return {"type": "heal", "amount": actual, "message": "%s is fully healed!" % character.character_name}

		"give_item":
			var item_id: String = effect.get("item_id", "")
			if not item_id.is_empty():
				character.inventory.add_item(item_id)
				var item_data := DataLoader.get_item(item_id)
				var item_name: String = item_data.get("name", item_id)
				return {"type": "give_item", "item_id": item_id, "message": "%s received %s!" % [character.character_name, item_name]}

		"take_gold":
			var amount: int = int(effect.get("value", 0))
			var taken := mini(amount, character.inventory.gold)
			character.inventory.gold -= taken
			return {"type": "take_gold", "amount": taken, "message": "%s lost %d gold!" % [character.character_name, taken]}

		"spend_resource":
			var resource_id := str(effect.get("resource_id", effect.get("feature_id", "")))
			var spend_amount := maxi(1, int(effect.get("amount", 1)))
			var remaining := int(character.feature_uses.get(resource_id, -1))
			if resource_id.is_empty() or remaining < spend_amount:
				return {"type": "spend_resource", "success": false, "amount": 0, "message": "%s could not spend %s." % [character.character_name, resource_id]}
			character.feature_uses[resource_id] = remaining - spend_amount
			return {"type": "spend_resource", "success": true, "amount": spend_amount, "message": "%s spent %d use(s) of %s." % [character.character_name, spend_amount, resource_id]}

		"restore_resource":
			var restore_id := str(effect.get("resource_id", effect.get("feature_id", "")))
			var restore_amount := maxi(1, int(effect.get("amount", 1)))
			var current := int(character.feature_uses.get(restore_id, -1))
			var maximum := _feature_max_uses(character, restore_id)
			if restore_id.is_empty() or current < 0 or maximum < 0:
				return {"type": "restore_resource", "success": false, "amount": 0, "message": "%s has no resource named %s." % [character.character_name, restore_id]}
			var restored := mini(restore_amount, maximum - current)
			character.feature_uses[restore_id] = current + restored
			return {"type": "restore_resource", "success": true, "amount": restored, "message": "%s restored %d use(s) of %s." % [character.character_name, restored, restore_id]}

		"grant_condition":
			var condition_name: String = effect.get("condition", "")
			var duration: int = int(effect.get("duration", 3))
			if not condition_name.is_empty():
				character.add_condition(condition_name, duration)
				return {"type": "condition", "condition": condition_name, "duration": duration, "message": "%s is now %s for %d turns!" % [character.character_name, condition_name, duration]}

		"apply_condition":
			var applied_condition := str(effect.get("condition", ""))
			var applied_duration := int(effect.get("duration", 3))
			if not applied_condition.is_empty():
				character.add_condition(applied_condition, applied_duration)
				return {"type": "condition", "condition": applied_condition, "duration": applied_duration, "message": "%s is now %s for %d turns!" % [character.character_name, applied_condition, applied_duration]}

		"remove_condition":
			var condition_name: String = effect.get("condition", "")
			if not condition_name.is_empty():
				character.remove_condition(condition_name)
				return {"type": "remove_condition", "condition": condition_name, "message": "%s is no longer %s!" % [character.character_name, condition_name]}

		"remove_all_conditions":
			character.conditions.clear()
			return {"type": "remove_all_conditions", "message": "%s is cured of all conditions!" % character.character_name}

		"gold":
			var amount: int = int(effect.get("value", 0))
			character.inventory.gold += amount
			return {"type": "gold", "amount": amount, "message": "%s gained %d gold!" % [character.character_name, amount]}

		"rest":
			character.reset_rest_features()
			return {"type": "rest", "message": "%s takes a rest and recovers abilities." % character.character_name}

		"start_combat":
			var monster_ids: Array = effect.get("monsters", [])
			return {"type": "start_combat", "monster_ids": monster_ids, "message": "Combat begins!"}

		"set_concentration":
			var spell_id := str(effect.get("spell_id", ""))
			if spell_id.is_empty():
				return {}
			character.concentrating_on = effect.duplicate(true)
			return {"type": "concentration", "spell_id": spell_id, "message": "%s begins concentrating." % character.character_name}

		"clear_concentration":
			character.concentrating_on.clear()
			return {"type": "concentration", "message": "%s ends concentration." % character.character_name}

		"stat_modifier", "ac_bonus", "speed_modifier", "movement":
			var stat_key := str(effect.get("key", effect.get("stat", "")))
			if effect_type == "ac_bonus":
				stat_key = "AC"
			elif effect_type in ["speed_modifier", "movement"]:
				stat_key = "speed"
			var stat_amount := _level_scaled_amount(effect, character.level)
			var stat_duration := int(effect.get("duration", 1))
			if stat_key.is_empty() or stat_amount == 0:
				return {}
			character.add_modifier("stat", stat_key, stat_amount, stat_duration)
			return {"type": "stat_modifier", "key": stat_key, "amount": stat_amount, "duration": stat_duration, "message": "%s's %s changes by %d for %d turns." % [character.character_name, stat_key, stat_amount, stat_duration]}

		"roll_modifier":
			var roll_key := str(effect.get("key", ""))
			var roll_amount := _level_scaled_amount(effect, character.level)
			var roll_duration := int(effect.get("duration", 1))
			if roll_key.is_empty() or roll_amount == 0:
				return {}
			character.add_modifier("roll", roll_key, roll_amount, roll_duration)
			return {"type": "roll_modifier", "key": roll_key, "amount": roll_amount, "duration": roll_duration, "message": "%s gains a %s roll modifier of %+d for %d turns." % [character.character_name, roll_key, roll_amount, roll_duration]}

		"pact_magic_recovery":
			var recovery_fraction := float(effect.get("fraction", 0.5))
			var recovery_by_level: Dictionary = effect.get("fraction_by_level", {})
			var recovery_level := 0
			for level_key in recovery_by_level:
				var attained_level := int(level_key)
				if attained_level <= character.level and attained_level > recovery_level:
					recovery_level = attained_level
			if recovery_level > 0:
				recovery_fraction = float(recovery_by_level[str(recovery_level)])
			var recovered := character.recover_pact_magic_slots(recovery_fraction)
			return {"type": "pact_magic_recovery", "amount": recovered, "message": "%s recovers %d Pact Magic slot%s." % [character.character_name, recovered, "" if recovered == 1 else "s"]}

		"innate_sorcery":
			var duration := maxi(1, int(effect.get("duration", 10)))
			character.add_condition("innate_sorcery", duration)
			return {"type": "innate_sorcery", "duration": duration, "message": "%s unleashes Innate Sorcery for %d turns." % [character.character_name, duration]}

		"reaction":
			var reaction_id := str(effect.get("reaction", ""))
			if reaction_id.is_empty():
				return {}
			return {"type": "reaction", "reaction": reaction_id, "message": "%s has %s available as a reaction." % [character.character_name, reaction_id.replace("_", " ")]}

		"teleport_random":
			return {"type": "teleport_random", "message": "%s is teleported to a random location!" % character.character_name}

		"reveal_map":
			var radius: int = int(effect.get("radius", 2))
			return {"type": "reveal_map", "radius": radius, "message": "The surrounding area is revealed!"}

		"reduce_speed":
			if SpellEffects.has_spell(character, "freedom_of_movement"):
				return {"type": "reduce_speed", "value": 0, "duration": int(effect.get("duration", 1)), "message": "%s is unaffected by the movement reduction." % character.character_name}
			var speed_reduction := int(effect.get("value", 2))
			var speed_duration := int(effect.get("duration", 1))
			character.add_modifier("stat", "speed", -speed_reduction, speed_duration)
			return {"type": "reduce_speed", "value": speed_reduction, "duration": speed_duration, "message": "%s's movement is reduced by %d for %d turns." % [character.character_name, speed_reduction, speed_duration]}

		"vision_bonus":
			var vision_amount := int(effect.get("value", 2))
			var vision_duration := int(effect.get("duration", 1))
			character.add_modifier("stat", "vision", vision_amount, vision_duration)
			return {"type": "vision_bonus", "value": vision_amount, "duration": vision_duration, "message": "%s's vision improves by %d for %d turns." % [character.character_name, vision_amount, vision_duration]}

		"area_selection":
			return resolve_area_selection(effect)

		_:
			push_warning("[EventResolver] Unknown effect type: %s" % effect_type)
			return {}

	return {}

static func apply_effects(character: Character, effects: Array, roller: Character = null, casting_ability: String = "") -> Array[Dictionary]:
	var results: Array[Dictionary] = []

	for effect in effects:
		var effect_type: String = effect.get("type", "")
		var result := _apply_single_effect(character, effect, roller, casting_ability)
		if not result.is_empty():
			results.append(result)

	return results


## Apply a single effect to a character.

static func roll_event(table_id: String) -> Dictionary:
	var table := DataLoader.get_event_table(table_id)
	if table.is_empty():
		push_warning("[EventSystem] Event table not found: %s" % table_id)
		return {}

	var events: Array = table.get("events", [])
	if events.is_empty():
		return {}

	# Calculate total weight
	var total_weight := 0
	for event in events:
		total_weight += int(event.get("weight", 1))

	# Roll weighted random
	var roll := randi_range(1, total_weight)
	var cumulative := 0
	for event in events:
		cumulative += int(event.get("weight", 1))
		if roll <= cumulative:
			return event

	# Fallback (shouldn't happen)
	return events[0]


## Get the event table ID for a terrain type from the active campaign.

static func get_table_for_terrain(terrain_name: String) -> String:
	var campaign: Dictionary = GameManager.active_campaign
	var event_tables: Dictionary = campaign.get("map", {}).get("event_tables", {})
	return event_tables.get(terrain_name, "")


## Trigger an event for a hex tile. Returns the event data or empty dict.

func are_win_conditions_met() -> bool:
	var win_cond := get_win_condition()
	if win_cond.is_empty() or str(win_cond.get("type", "")) != "goal":
		return false
	for goal in win_cond.get("goals", []):
		match str(goal.get("type", "")):
			"collect_item":
				var required := int(goal.get("count", 1))
				var total := 0
				for character in PartyManager.get_active_characters():
					total += character.inventory.count_item(str(goal.get("item_id", "")))
				if total < required:
					return false
			"defeat_monster":
				if str(goal.get("monster_id", "")) not in defeated_monsters:
					return false
			_:
				return false
	return true


## Check a milestone trigger. Returns true if a milestone was activated.

func check_milestone(trigger: String) -> bool:
	if trigger in completed_milestones:
		return false
	var milestones: Array = get_milestones()
	for milestone in milestones:
		if milestone.get("trigger", "") == trigger:
			# Apply milestone effects
			var effects: Array = milestone.get("effects", [])
			for effect in effects:
				_apply_milestone_effect(effect)
			completed_milestones.append(trigger)
			return true
	return false


## Claim a dungeon's one-time clear transition. Returns false on replay.

func mark_dungeon_cleared(dungeon_id: String) -> bool:
	if dungeon_id.is_empty() or dungeon_id in cleared_dungeons:
		return false
	cleared_dungeons.append(dungeon_id)
	return true

func claim_reward(reward_id: String) -> bool:
	if reward_id.is_empty() or reward_id in claimed_rewards:
		return false
	claimed_rewards.append(reward_id)
	return true
